SELECT timeSeriesStoreTags(id, tags, '__name__', metric_name) FROM default.`.inner_id.tags.a95d167f-9ea5-48c0-bd90-d75fef42985c` ANY LEFT JOIN (SELECT id, 1 AS matched FROM default.`.inner_id.timeranges.a95d167f-9ea5-48c0-bd90-d75fef42985c` WHERE and(greaterOrEquals(max_time, toDateTime64(toDecimal128('1794609600.001', 3), 3)), lessOrEquals(min_time, toDateTime64(toDecimal128('1794620700', 3), 3)), indexHint(and(greaterOrEquals(id, tuple(sipHash64('metric_0'), toUUID('00000000-0000-0000-0000-000000000000'))), lessOrEquals(id, tuple(sipHash64('metric_0'), toUUID('ffffffff-ffff-ffff-ffff-ffffffffffff'))))), `not`(notEquals(tupleElement(id, 1), sipHash64('metric_0'))))) AS time_ranges_subquery USING (id) WHERE and(and(equals(metric_name, 'metric_0'), equals(arrayElement(tags, 'label_a'), 'v1'), equals(arrayElement(tags, 'label_b'), 'v1'), equals(arrayElement(tags, 'label_c'), 'v1')), or(equals(time_ranges_subquery.matched, 1), notEquals(tupleElement(id, 1), sipHash64('metric_0'))))
